package upload

import (
  "log"
  "os"
  "sync"
)

func UploadAll(paths []string) error {
  var wg sync.WaitGroup
  for _, p := range paths {
    wg.Add(1)
    go func() {
      defer wg.Done()
      f, err := os.Open(p)
      if err != nil {
        log.Printf("open %s: %v", p, err)
        return
      }
      defer f.Close()
      if err := put(f); err != nil {
        log.Printf("put %s: %v", p, err)
      }
    }()
  }
  wg.Wait()
  return nil
}

