func uploadOne(path string) (err error) {
  f, err := os.Open(path)
  if err != nil {
    return fmt.Errorf("open %s: %w", path, err)
  }
  defer func() {
    if cerr := f.Close(); cerr != nil && err == nil {
      err = fmt.Errorf("close %s: %w", path, cerr)
    }
  }()
  return put(f)
}

